// Trimmed shapes of the SRD 5.1 data generated by scripts/build-srd.ts.

export interface SrdFeature {
  name: string;
  desc: string;
}

export interface SrdAction extends SrdFeature {
  attackBonus?: number;
  /** e.g. "1d6+2 slashing" or "2d6+5 bludgeoning + 1d12 acid" */
  damage?: string;
}

export interface SrdMonster {
  id: string;
  name: string;
  size: string;
  type: string;
  alignment: string;
  ac: number;
  acNote?: string;
  hp: number;
  hpRoll: string;
  speed: string;
  /** STR, DEX, CON, INT, WIS, CHA */
  abilities: [number, number, number, number, number, number];
  saves?: string;
  skills?: string;
  vulnerabilities?: string;
  resistances?: string;
  immunities?: string;
  conditionImmunities?: string;
  senses: string;
  languages: string;
  cr: number;
  xp: number;
  profBonus: number;
  traits: SrdFeature[];
  actions: SrdAction[];
  reactions: SrdFeature[];
  legendary: SrdFeature[];
}

export interface SrdSpell {
  id: string;
  name: string;
  level: number;
  school: string;
  castingTime: string;
  range: string;
  components: string;
  duration: string;
  concentration: boolean;
  ritual: boolean;
  desc: string;
  higherLevel?: string;
  classes: string[];
  attackType?: string;
  save?: string;
  damageType?: string;
  damageAtSlot?: Record<string, string>;
  damageAtCharLevel?: Record<string, string>;
  healAtSlot?: Record<string, string>;
  area?: string;
}

export interface SrdCondition {
  id: string;
  name: string;
  desc: string;
}

export interface SrdMagicItem {
  id: string;
  name: string;
  category: string;
  rarity: string;
  desc: string;
}

export interface SrdWeapon {
  id: string;
  name: string;
  category: string;
  damage: string;
  damageType: string;
  twoHanded?: string;
  properties: string[];
  range?: string;
  cost: string;
  weight?: number;
}

export interface SrdArmor {
  id: string;
  name: string;
  category: string;
  baseAc: number;
  dexBonus: boolean;
  maxDexBonus?: number;
  stealthDisadvantage: boolean;
  strMinimum: number;
  cost: string;
}
